// 서명 확인 — 웹훅 URL만 알면 누구나 POST할 수 있다. 서명이 없으면 가짜 "승인 필요" 알림을 외부에서 만들 수 있다.
// 서명 대상은 파싱된 JSON이 아니라 받은 그대로의 본문이다(키 순서가 바뀌면 같은 내용도 다른 서명이 된다).
const crypto = require('crypto');
const secret = $env.DBTOWER_N8N_SECRET;
if (!secret) {
  throw new Error('DBTOWER_N8N_SECRET이 없습니다 — 서명을 확인할 수 없어 처리하지 않습니다');
}
const item = $input.first();
const headers = item.json.headers || {};
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const timestamp = headers['x-dbtower-timestamp'];
const signature = headers['x-dbtower-signature'];
if (!timestamp || !signature) {
  throw new Error('서명 헤더가 없습니다');
}
const age = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
if (!Number.isFinite(age) || age > 300) {
  throw new Error('만료된 요청입니다(5분 초과) — 재생 공격 차단');
}
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(Buffer.concat([Buffer.from(timestamp + '.'), raw])).digest('hex');
const ok = expected.length === signature.length && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
if (!ok) {
  throw new Error('서명이 일치하지 않습니다');
}
const body = JSON.parse(raw.toString('utf8'));
// 라우팅 값은 DBTower가 확정한 것만 쓴다 — 본문의 다른 문장으로 분기하지 않는다
return [{ json: {
  jobId: body.jobId,
  type: body.type,
  status: body.status,
  requester: body.requester,
  scopeTeam: body.scopeTeam,
  instanceId: body.instanceId,
  approvalRequired: body.approvalRequired === true,
  ruleFindings: body.ruleFindings || [],
  unverifiedClaimCount: body.unverifiedClaimCount || 0,
  failureReason: body.failureReason || null,
  url: body.url,
  route: body.status !== 'COMPLETED' ? 'failed' : (body.approvalRequired === true ? 'approval' : 'informational'),
} }];
